from decimal import Decimal, getcontext, ROUND_DOWN, InvalidOperation

getcontext().prec = 80


def _to_decimal(value):
    """Convierte la cadena de entrada a Decimal; si no es numérica devuelve 0 (supuesto)."""
    if value is None:
        return Decimal(0)
    s = str(value).strip()
    if s == "":
        return Decimal(0)
    try:
        d = Decimal(s)
    except (InvalidOperation, ValueError):
        return Decimal(0)
    if not d.is_finite():
        return Decimal(0)
    return d


def _pic_unsigned(d, int_digits, scale):
    """Simula el almacenamiento en una PIC sin signo: se pierde el signo,
    se truncan los decimales (ROUND_DOWN) y los dígitos enteros por la izquierda."""
    d = abs(d)
    q = Decimal(1).scaleb(-scale)  # 10^-scale
    d = d.quantize(q, rounding=ROUND_DOWN)
    modulus = Decimal(10) ** int_digits
    int_part = int(d)  # parte entera (d es positivo)
    frac_part = d - Decimal(int_part)
    int_part = int_part % int(modulus)  # truncamiento por la izquierda
    return Decimal(int_part) + frac_part


def _fmt_9n(d, n):
    """Formato PIC 9(n): n dígitos con ceros a la izquierda."""
    v = int(_pic_unsigned(d, n, 0))
    return str(v).zfill(n)


def _fmt_9999v99_edited(d):
    """Formato PIC 9999.99 (numérico editado): 4 dígitos, punto literal, 2 decimales."""
    v = _pic_unsigned(d, 4, 2)
    cents = int((v * 100).to_integral_value(rounding=ROUND_DOWN))
    int_part = cents // 100
    dec_part = cents % 100
    return str(int_part).zfill(4) + "." + str(dec_part).zfill(2)


def run(inp: dict) -> dict:
    # Valores iniciales: el FD no tiene VALUE; se asume que la cadena vacía equivale a cero.
    from_account = _to_decimal(inp.get("from_account"))
    to_account = _to_decimal(inp.get("to_account"))
    amount = _to_decimal(inp.get("amount"))

    # ACCEPT FromAccount  (PIC 9(5))
    from_str = _fmt_9n(from_account, 5)
    # ACCEPT ToAccount    (PIC 9(5))
    to_str = _fmt_9n(to_account, 5)
    # ACCEPT Amount       (PIC 9999.99)
    amount_str = _fmt_9999v99_edited(amount)

    # WRITE TransactionDetails: registro de 17 caracteres (5 + 5 + 7)
    record = from_str + to_str + amount_str

    return {
        "transaction_record": record,
        "status": "OK",
    }
